import csv,hashlib,json,platform,statistics
from pathlib import Path
root=Path('outputs/native-flow/sst-workspace')
def record(p):
 p=Path(p);return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
def read(p):return json.loads(Path(p).read_text())
runs={}
for name in ['before-1','after-1','after-2','before-2','after-full']:
 folder=root/name
 if not (folder/'runtime.json').exists():continue
 entry={'runtime':read(folder/'runtime.json'),'files':[record(p) for p in sorted(folder.iterdir()) if p.is_file()]}
 if (folder/'flow.diagnostics.json').exists():entry['diagnostics']=read(folder/'flow.diagnostics.json')
 if (folder/'audit.json').exists():entry['audit']={k:v for k,v in read(folder/'audit.json').items() if k!='plateWallSamples'}
 entry['completedFixed100']=name!='after-full' and entry.get('diagnostics',{}).get('iterations')==100 and entry['diagnostics']['stopReason']=='iteration-limit'
 runs[name]=entry
means={}
for method in ['before','after']:
 samples=[e for n,e in runs.items() if n.startswith(method+'-') and e['completedFixed100']]
 if samples:means[method]={'samples':len(samples),'nativeSeconds':statistics.mean(e['diagnostics']['solveSeconds'] for e in samples),
  'scalarSetupSeconds':statistics.mean(e['diagnostics']['performance']['scalarSolves']['setupSeconds'] for e in samples)}
def equal_csv(a,b):
 out={}
 for suffix in ['.cells.csv','.faces.csv','.history.csv']:
  # History is written at the unsuffixed run prefix even for diagnostic fields.
  aa=Path(str(a).removesuffix('.unconverged')+suffix) if suffix=='.history.csv' else Path(str(a)+suffix)
  bb=Path(str(b).removesuffix('.unconverged')+suffix) if suffix=='.history.csv' else Path(str(b)+suffix)
  out[suffix]={'before':record(aa),'after':record(bb),'identical':aa.read_bytes()==bb.read_bytes()}
 return out
comparisons={}
for n in ['after-1','after-2','before-2']:
 if runs.get(n,{}).get('completedFixed100'):
  comparisons[n]=equal_csv(root/'before-1/flow.unconverged',root/n/'flow.unconverged')
assert all(v['identical'] for c in comparisons.values() for v in c.values()), 'fixed-work numerical fields changed'
sources=['include/cartmesh2d/fv/ScalarTransport2D.hpp','include/cartmesh2d/fv/Sst2003m2D.hpp','src/fv/ScalarTransport2D.cpp','src/fv/Sst2003m2D.cpp','src/fv/SstRans2D.cpp','tests/sst_rans_probe.cpp','tests/sst_rans_test.cpp','tests/scalar_workspace_test.cpp']
study={'scope':'Explicit sparse storage reuse in native SST; unchanged equations and original stopping gates; physical accuracy unchanged',
 'baseCommit':'65319e3','host':platform.platform(),'mesh':record('outputs/native-flow/sst-normal-refinement/midpoint/mesh.cm2d'),
 'beforeBinary':record(root/'before-probe'),'afterBinary':record('build/cartmesh2d_sst_rans_probe'),
 'sourceFiles':[record(p) for p in sources],'runs':runs,'fixedWorkMeans':means,'fixedWorkByteComparisons':comparisons,
 'timeScope':'Native solve time; ABBA serial fixed-work runs. Full comparison is one previously recorded before run and one new after run. Process times include polling and I/O.',
 'thresholdsChanged':False,'rawRoot':str(root)}
if runs.get('after-full',{}).get('audit',{}).get('valid'):
 baseline=Path('outputs/native-flow/sst-pressure-comparison/aggregation-full')
 study['fullComparison']={'baselineDiagnostics':read(baseline/'flow.diagnostics.json'),'baselineAudit':record(baseline/'audit.json'),
  'byteComparison':equal_csv(baseline/'flow',root/'after-full/flow')}
 assert all(v['identical'] for v in study['fullComparison']['byteComparison'].values()), 'full numerical fields changed'
 old=read(baseline/'flow.json');new=read(root/'after-full/flow.json')
 keys=['case','flatPlateLeadingEdge','flatPlateTop','model','scope','nu','speed','inletK','inletOmega','initialK','initialOmega','tolerance','scalarRelativeTolerance','scalarAbsoluteTolerance','scalarCellTolerance','convection','viscousStress','turbulenceUpdatesPerIteration','turbulenceCompletionUpdates','scalarCorrectionsPerUpdate','scalarPreconditioner','pressurePreconditioner','cells']
 assert all(old[k]==new[k] for k in keys)
 study['matchingFullRunControls']={k:old[k] for k in keys}
prior=read('artifacts/current/native-sst-pressure-comparison.json')
assert study['beforeBinary']['sha256']==prior['binary']['sha256'], 'before binary does not match published baseline'
study['baselineEvidence']=record('artifacts/current/native-sst-pressure-comparison.json')
for line in (root/'hashes-full-pre-run.sha256').read_text().splitlines():
 digest,path=line.split(None,1)
 if path in ['build/cartmesh2d_sst_rans_probe','outputs/native-flow/sst-workspace/before-probe','outputs/native-flow/sst-normal-refinement/midpoint/mesh.cm2d']:
  assert record(path)['sha256']==digest, 'timed executable/input changed'
study['runHashRecords']=[record(p) for p in sorted(root.glob('hashes-*.sha256'))]
for name in ['run_one.py','summarize.py','plot.py']:
 p=root/name
 if p.exists():study.setdefault('reproductionSources',{})[name]={'file':record(p),'source':p.read_text()}
for name in ['build.log','ctest.log','frontend.log']:
 p=root/name
 if p.exists():study.setdefault('validationLogs',[]).append(record(p))
Path('artifacts/current/native-sst-workspace.json').write_text(json.dumps(study,indent=2,allow_nan=False)+'\n')
print(json.dumps({'means':means,'fullAccepted':runs.get('after-full',{}).get('audit',{}).get('valid',False),'fixedWorkBytesIdentical':all(v['identical'] for c in comparisons.values() for v in c.values())},indent=2))
